head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > modifyUncheckStatus]<br/>Body Column 정보를 사용하여 특정 Column 에서 체크되지 않은 Row 의 상태값을 일괄로 변경합니다.",
    "validation" : [
        "Body Column 이 inputType 이 'checkbox','radio','custom' 인 경우에만 동작해야 합니다.",
        "columnInfo(필수) 파라미터로 Row 의 상태값을 변경할 Body Column 의 인덱스를 설정해야 합니다.",
        "Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "status(필수) 파라미터로 체크되지 않은 Row 에 일괄 적용할 Row 상태값을 'R','U','C','D','V' 중 하나로 설정해야 합니다.",
        "status 를 'R' 로 설정 시, 체크되지 않은 Row 가 로딩된 '초기' 상태(rowStatus 'R' / statusValue 0)로 일괄 변경되어야 합니다.",
        "status 를 'U' 로 설정 시, 체크되지 않은 Row 가 '갱신'된 상태(rowStatus 'U' / statusValue 1)로 일괄 변경되어야 합니다.",
        "status 를 'C' 로 설정 시, 체크되지 않은 Row 가 '삽입'된 상태(rowStatus 'C' / statusValue 2)로 일괄 변경되어야 합니다.",
        "status 를 'D' 로 설정 시, 체크되지 않은 Row 가 '삭제'된 상태(rowStatus 'D' / statusValue 3)로 일괄 변경되어야 합니다.",
        "status 를 'V' 로 설정 시, 체크되지 않은 Row 가 '삽입 후 삭제'된 상태(rowStatus 'V' / statusValue 4)로 일괄 변경되어야 합니다.",
        "status 를 'R','U','C','D','V' 5 개 상태값이 아닌 값으로 설정하면 메소드가 실행되지 않아야 합니다.",
        "inputType='custom' 이면 실제 Cell 의 inputType 이 'checkbox','radio' 인 Cell 만 처리해야 합니다.",
        "체크되지 않은 Row 의 상태만 일괄 변경하고, 체크된 Row 의 상태는 유지되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    // 숨김 컬럼(인덱스1 birth) 을 포함하여 인덱스가 매겨지므로 checkbox 대상 chk 는 인덱스 2
    $c.gcm.createLabel('label="[전제] 컬럼 0:name(text) / 1:birth(text·숨김) / 2:chk(checkbox) / 3:rdo(radio) / 4:cst(custom). 숨김 컬럼(1) 도 포함해 인덱스 부여 -> chk 는 인덱스 2.\n체크 상태(바인딩 데이터 1/0): chk 체크=Row0,2,4 (미체크=Row1,3) / rdo(단일)=Row1 (미체크=Row0,2,3,4) / cst 체크셀=Row0,2 (Row1 text·Row3 radio·Row4 checkbox 는 미체크).\n[절차] columnInfo(인덱스) 와 status 선택 후 실행 -> 매 실행 전 전체 Row 를 U(갱신) 로 초기화한 뒤 미체크 Row 만 지정 status 로 일괄 변경.\n[확인] 각 Row 의 rowStatus 출력에서 미체크 Row 만 status 로 바뀌고 체크 Row 는 U 로 유지됨을 확인."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    // - name  : text
    // - birth : text (setColumnVisible(1,false) 로 숨김 -> 인덱스는 유지)
    // - chk   : checkbox(binary) 원본값 1/0 -> 체크 조회 대상 Column(인덱스 2)
    // - rdo   : radio(binary) 원본값 1/0 (단일선택)
    // - cst   : custom 컬럼 (행별 inputType 부여)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="birth" name="birth" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="rdo" name="rdo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cst" name="cst" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // chk : Row0/Row2/Row4 = 체크("1"), Row1/Row3 = 미체크("0")
    // rdo : radio 단일선택 -> Row1 만 "1"
    // cst : Row0=checkbox(1=체크), Row1=text, Row2=checkbox(1=체크), Row3=radio(0=미체크), Row4=checkbox(0=미체크)
    let jsonData = [
        { "name": "HONG", "birth": "19850315", "chk": "1", "rdo": "0", "cst": "1"    },
        { "name": "KIM",  "birth": "19900720", "chk": "0", "rdo": "1", "cst": "text" },
        { "name": "LEE",  "birth": "19880103", "chk": "1", "rdo": "0", "cst": "1"    },
        { "name": "PARK", "birth": "19920512", "chk": "0", "rdo": "0", "cst": "0"    },
        { "name": "CHOI", "birth": "19870928", "chk": "1", "rdo": "0", "cst": "0"    }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    // setCellInputTypeCustom=true -> custom 컬럼에 setCellInputType 으로 행별 inputType 부여 가능
    let properties = {
        dataList: "data:dlt_bind",
        setCellInputTypeCustom: "true",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 5컬럼)
    // 마지막 cst 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:720px;height:260px;">';
    strTarget += '<w2:caption style="" id="caption1" value="modifyUncheckStatus 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="생년월일(숨김)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="chk(checkbox)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol4" value="rdo(radio)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol5" value="cst(custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : name (text)
    strTarget += '<w2:column width="120" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 1 : birth (text) - setColumnVisible(1,false) 로 숨김 (인덱스는 유지)
    strTarget += '<w2:column width="120" style="" inputType="text" id="birth" dataList="birth"></w2:column>';
    // index 2 : chk (checkbox, valueType=binary) - trueValue="1" falseValue="0" -> 체크 조회 대상 Column
    strTarget += '<w2:column width="120" style="" inputType="checkbox" valueType="binary" id="chk" dataList="chk" trueValue="1" falseValue="0"></w2:column>';
    // index 3 : rdo (radio, valueType=binary) - 단일선택
    strTarget += '<w2:column width="120" style="" inputType="radio" valueType="binary" id="rdo" dataList="rdo" trueValue="1" falseValue="0"></w2:column>';
    // index 4 : cst (custom) - 행별 inputType 혼합 (setCellInputType 으로 지정), width="*"
    strTarget += '<w2:column width="*" style="" inputType="custom" id="cst" dataList="cst" trueValue="1" falseValue="0"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 두번째 컬럼(birth, 인덱스1) 숨김 -> 숨겨진 Column 도 포함하여 인덱스가 매겨짐을 검증 (@param columnInfo)
    target1.setColumnVisible(1, false);

    // cst(custom) 컬럼 행별 inputType 부여 (@spec1)
    //  Row0 = checkbox(1=체크), Row1 = text(체크 대상 아님), Row2 = checkbox(1=체크), Row3 = radio(0=미체크), Row4 = checkbox(0=미체크)
    target1.setCellInputType(0, "cst", { inputType: "checkbox" });
    target1.setCellInputType(1, "cst", { inputType: "text" });
    target1.setCellInputType(2, "cst", { inputType: "checkbox" });
    target1.setCellInputType(3, "cst", { inputType: "radio" });
    target1.setCellInputType(4, "cst", { inputType: "checkbox" });
}



// modifyUncheckStatus 실행 : par_columnInfo(컬럼 인덱스) / par_status 로 호출
//  - columnInfo 는 컬럼 인덱스(Number, 숨김 컬럼 포함) 로 전달
//  - 매 실행 전 전체 Row 를 U 로 초기화 -> 미체크 Row 만 지정 status 로 바뀌고 체크 Row 는 U 유지됨을 확인
//  - status 가 R/U/C/D/V 5개 값이 아니면(예: X) 메소드 미실행 -> 전체 U 유지
scwin.btn_modifyUncheckStatus_onclick = function () {
    // columnInfo 는 컬럼 인덱스(Number) 로 전달
    let colIndex = Number(par_columnInfo.getValue());
    let status = par_status.getValue();

    // 매 실행 전 전체 Row 를 U(갱신) 상태로 초기화
    let len = dlt_bind.getRowCount();
    for (let i = 0; i < len; i++) {
        dlt_bind.modifyRowStatus(i, "U");
    }

    // 체크되지 않은 Row 인덱스 (바인딩 데이터 1/0 값이 체크 상태 사전조건)
    let uncheckedRows = target1.getUncheckedIndex(colIndex);

    // 체크되지 않은 Row 상태 일괄 변경
    target1.modifyUncheckStatus(colIndex, status);

    // 각 Row 의 rowStatus 조회
    let after = [];
    for (let i = 0; i < len; i++) {
        after.push(i + "=" + dlt_bind.getRowStatus(i));
    }

    let out = "modifyUncheckStatus(" + colIndex + ", " + status + ") -> 미체크 Row [" + uncheckedRows.join(", ") + "] / rowStatus(전체 U 초기화 후): " + after.join(" ");
    wf_body_bottom.getObj("scwin").setReturnValue(out);
}
